<?php if($rows):?><section class="panel"><header class="panel-heading"><h4 class="panel-title">Calculated Marks Overview</h4></header><div class="panel-body table-responsive"><table class="table table-bordered table-hover"><thead><tr><th>Roll</th><th>Student</th><th>Subject Scores</th><th>Total</th><th>Overall %</th><th>State</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['student']['roll']?></td><td><?=html_escape($r['student']['student_name'])?></td><td><?php foreach($r['subjects'] as $s):?><div><?=html_escape($s['name'])?>: <strong><?=$s['result']['display_score']!==null?$s['result']['display_score'].'%':'Incomplete'?></strong><?php if($s['result']['errors']):?> <span class="text-danger"><?=html_escape(implode(', ',$s['result']['errors']))?></span><?php endif?></div><?php endforeach?></td><td><?=number_format($r['overall']['total'],2)?></td><td><?=$r['overall']['display_percentage']!==null?$r['overall']['display_percentage'].'%':'—'?></td><td><span class="label label-<?=$r['overall']['complete']?'success':'warning'?>"><?=$r['overall']['complete']?'Complete':'Incomplete'?></span></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>

